/**
 * #2829 W9a (SC-29) — an empty planned page is hidden from search until it
 * has content, then listed again on its own (no republish).
 *
 * A planned offering page is a list page for trips, events or experiences.
 * It is EMPTY while every live grid on it shows its empty state (the feed —
 * or the publication's snapshot when Core is unreachable — has nothing for
 * it) and it carries no trip history. Worked out per request from the same
 * selection the grids draw with, so "empty" here and the empty state a
 * visitor sees can never disagree.
 */
import { isLiveOfferingGrid } from "./blocks.ts";
import { selectGridOfferings, type OfferingGridConfig, type SiteOffering } from "./offerings.ts";

const PLANNED_COLLECTIONS: readonly string[] = ["trips", "events", "experiences"];

type PageLike = {
  kind: string;
  collection?: string;
  blocks: ReadonlyArray<{ type: string; [field: string]: unknown }>;
};

export function isPlannedOfferingPage(page: PageLike): boolean {
  return page.kind === "collection_index" &&
    typeof page.collection === "string" && PLANNED_COLLECTIONS.includes(page.collection) &&
    page.blocks.some((block) => isLiveOfferingGrid(block));
}

/** True while a planned offering page has nothing to list (never for any other page). */
export function plannedPageIsEmpty(page: PageLike, offerings: readonly SiteOffering[], now: Date): boolean {
  if (!isPlannedOfferingPage(page)) return false;
  if (page.blocks.some((block) => block.type === "offering_history")) return false;
  return page.blocks.filter((block) => isLiveOfferingGrid(block)).every((block) => {
    const config: OfferingGridConfig = {
      kind: block.kind as OfferingGridConfig["kind"],
      mode: (block.mode as OfferingGridConfig["mode"]) ?? "upcoming",
      ...(Array.isArray(block.offering_ids) ? { offering_ids: block.offering_ids as Array<{ id: string }> } : {}),
      ...(typeof block.limit === "number" ? { limit: block.limit } : {}),
    };
    return selectGridOfferings(offerings, config, now).kind === "empty";
  });
}
